19	/*
20	 * Arm Helium (M-Profile Vector Extension, MVE) backend for the LTPF
21	 * pitch-detection hotspot, targeting Armv8.1-M cores (e.g. Cortex-M55).
22	 *
23	 * `dot()` accumulates int16 x int16 products into a 64-bit integer and
24	 * applies the rounding `(v + 32) >> 6`. MVE `vmlaldavaq_s16`
25	 * performs an 8-lane int16 x int16 -> int64 multiply-accumulate across the
26	 * vector; the integer sum and the subsequent rounding are therefore
27	 * identical to the scalar reference, i.e. the result is strictly bit-exact.
28	 *
29	 * This mirrors the NEON (`ltpf_neon.h`) and Arm DSP (`ltpf_arm.h`) backends
30	 * and hooks the same `dot` override point. Include this file before the
31	 * NEON/DSP backends in `ltpf.c` so its definitions take precedence on MVE
32	 * targets.
33	 */
34	
35	#if (__ARM_FEATURE_MVE & 1) && !defined(TEST_ARM) && !defined(TEST_NEON) \
36	        || defined(TEST_MVE)
37	
38	#ifndef TEST_MVE
39	#include <arm_mve.h>
40	#endif /* TEST_MVE */
41	
42	
43	/**
44	 * Return dot product of 2 vectors
45	 * a, b, n         The 2 vectors of size `n` (> 0 and <= 128)
46	 * return          round( sum( a[i] * b[i] ) / 64 ), as float
47	 *
48	 * The size `n` of vectors is a multiple of 16 (so also of 8).
49	 */
50	#ifndef dot
51	
52	LC3_HOT static inline float mve_dot(const int16_t *a, const int16_t *b, int n)
53	{
54	    int64_t v = 0;
55	
56	    for (int i = 0; i < (n >> 3); i++) {
57	        int16x8_t va = vldrhq_s16(a); a += 8;
58	        int16x8_t vb = vldrhq_s16(b); b += 8;
59	        v = vmlaldavaq_s16(v, va, vb);
60	    }
61	
62	    int32_t v32 = (v + (1 << 5)) >> 6;
63	    return (float)v32;
64	}
65	
66	#ifndef TEST_MVE
67	#define dot mve_dot
68	#endif
69	
70	#endif /* dot */
71	
72	#endif /* __ARM_FEATURE_MVE & 1 */
