1	#!/bin/sh
2	# Reproduce the codegen evidence behind PR #90, review question Q1:
3	#   "can the compiler optimize the original scalar loop in ltpf.c?"
4	#
5	# It compiles the pre-MVE (scalar) ltpf.c with both GCC and clang for an
6	# Armv8.1-M + MVE target, prints the dot() disassembly and each compiler's
7	# vectorizer report, then compiles the MVE backend the same way for contrast.
8	#
9	# Usage:
10	#   scripts/mve_codegen_check.sh [GCC] [CLANG]
11	#     GCC    path to arm-none-eabi-gcc (default: arm-none-eabi-gcc)
12	#     CLANG  path to clang            (default: clang)
13	#
14	# No hardware is required; only a cross toolchain is needed.
15	
16	set -eu
17	
18	GCC=${1:-arm-none-eabi-gcc}
19	CLANG=${2:-clang}
20	FLAGS="-march=armv8.1-m.main+dsp+mve.fp+fp.dp -mfloat-abi=hard -O3"
21	SCALAR_COMMIT=8e1e722   # main before the MVE backend was added
22	
23	command -v "$GCC"   >/dev/null || { echo "error: $GCC not found"   >&2; exit 1; }
24	command -v "$CLANG" >/dev/null || { echo "error: $CLANG not found" >&2; exit 1; }
25	
26	WORK=$(mktemp -d)
27	trap 'rm -rf "$WORK"' EXIT
28	
29	# Extract the scalar baseline from git (real TU, not a hand-written snippet).
30	git archive "$SCALAR_COMMIT" src include | tar -x -C "$WORK"
31	
32	echo "== toolchains =="
33	"$GCC" --version   | head -1
34	"$CLANG" --version | head -1
35	echo "== flags =="
36	echo "$FLAGS"
37	echo
38	
39	echo "================ GCC : scalar dot() ================"
40	"$GCC" $FLAGS -fno-inline -I"$WORK/include" -I"$WORK/src" \
41	    -S "$WORK/src/ltpf.c" -o - \
42	  | awk '/^dot:/{f=1} /^\.size[[:space:]]+dot,/{f=0} f' \
43	  | grep -oE '\b(vmlal[a-z0-9.]*|vmlaldav[a-z0-9.]*|smlal[a-z]*|ldrh[a-z.]*)\b' \
44	  | sort | uniq -c | sort -rn
45	
46	echo "---------------- GCC vectorizer report ----------------"
47	"$GCC" $FLAGS -I"$WORK/include" -I"$WORK/src" \
48	    -c "$WORK/src/ltpf.c" -o /dev/null \
49	    -fopt-info-vec-all="$WORK/gcc_vec.log" 2>&1 || true
50	grep -E 'ltpf\.c:44[0-9]' "$WORK/gcc_vec.log" 2>/dev/null \
51	  | sed 's#[^ ]*/src/ltpf\.c#src/ltpf.c#g; s/^/  /' | sort -u
52	echo
53	
54	echo "================ CLANG : scalar dot() ================"
55	"$CLANG" --target=thumbv8.1m.main-none-eabi $FLAGS -fno-inline \
56	    -I"$WORK/include" -I"$WORK/src" -S "$WORK/src/ltpf.c" -o - 2>/dev/null \
57	  | awk '/^dot:/{f=1} /^\.Lfunc_end/{f=0} f' \
58	  | grep -oE '\b(vmlal[a-z0-9.]*|vmlaldav[a-z0-9.]*|vmovlb[a-z0-9.]*|smlal[a-z]*|ldrh[a-z.]*)\b' \
59	  | sort | uniq -c | sort -rn
60	
61	echo "---------------- CLANG vectorizer report ----------------"
62	"$CLANG" --target=thumbv8.1m.main-none-eabi $FLAGS \
63	    -I"$WORK/include" -I"$WORK/src" -c "$WORK/src/ltpf.c" -o /dev/null \
64	    -Rpass=loop-vectorize -Rpass-missed=loop-vectorize 2>&1 \
65	  | grep -E 'ltpf\.c:44[0-9]' | sed 's#[^ ]*/src/ltpf\.c#src/ltpf.c#g; s/^/  /' | sort -u
66	echo
67	
68	echo "================ GCC : hand-written MVE backend (this branch) ================"
69	"$GCC" $FLAGS -fno-inline -I"$WORK/include" -Isrc -S src/ltpf.c -o - \
70	  | awk '/^mve_dot:/{f=1} /^\.size[[:space:]]+mve_dot,/{f=0} f' \
71	  | grep -oE '\b(vmlal[a-z0-9.]*|vmlaldav[a-z0-9.]*|smlal[a-z]*|ldrh[a-z.]*)\b' \
72	  | sort | uniq -c | sort -rn
