169	static void reset_window(struct lc3_profile *profile)
170	{
171	    memset(profile->stats, 0, sizeof(profile->stats));
172	    memset(profile->current, 0, sizeof(profile->current));
173	    memset(profile->samples, 0, sizeof(profile->samples));
174	    profile->touched = 0;
