187	void lc3_profile_init(struct lc3_profile *profile)
188	{
189	    uint32_t overhead = UINT32_MAX;
190	
191	    memset(profile, 0, sizeof(*profile));
192	
193	    for (int i = 0; i < 32; i++) {
194	        clock_t start = perf_gettime();
195	        uint32_t delta = elapsed_cycles(start);
196	
197	        if (delta < overhead)
198	            overhead = delta;
199	    }
200	
201	    profile->overhead = overhead == UINT32_MAX ? 0 : overhead;
202	    profile->warmup_remaining = LC3_PROFILE_WARMUP_FRAMES;
203	    profile->sequence = 1;
204	}
