206	void lc3_profile_frame_begin(struct lc3_profile *profile,
207	    int dt, int sr, int nbytes)
208	{
209	    bool config_changed = profile->config_valid &&
210	        (profile->dt != dt || profile->sr != sr || profile->nbytes != nbytes);
211	
212	    profile->active = false;
213	
214	    /* Preserve a completed snapshot until the cold path reports it. */
215	    if (profile->ready)
216	        return;
217	
218	    if (config_changed) {
219	        reset_window(profile);
220	        profile->warmup_remaining = LC3_PROFILE_WARMUP_FRAMES;
221	    }
222	
223	    profile->dt = dt;
224	    profile->sr = sr;
225	    profile->nbytes = nbytes;
226	    profile->config_valid = true;
227	
228	    memset(profile->current, 0, sizeof(profile->current));
229	    profile->touched = 0;
230	
231	    if (profile->warmup_remaining) {
232	        profile->warmup_remaining--;
233	        return;
234	    }
235	
236	    profile->active = true;
237	}
