244	void lc3_profile_stop(struct lc3_profile *profile,
245	    enum lc3_profile_metric metric, clock_t start)
246	{
247	    uint32_t delta;
248	
249	    if (!profile->active || metric < 0 || metric >= LC3_PROFILE_METRIC_COUNT)
250	        return;
251	
252	    delta = elapsed_cycles(start);
253	    delta = delta > profile->overhead ? delta - profile->overhead : 0;
254	
255	    if (UINT32_MAX - profile->current[metric] < delta)
256	        profile->current[metric] = UINT32_MAX;
257	    else
258	        profile->current[metric] += delta;
259	
260	    profile->touched |= 1u << metric;
261	}
262	
263	void lc3_profile_frame_end(struct lc3_profile *profile)
264	{
265	    if (!profile->active)
266	        return;
267	
268	    for (int metric = 0; metric < LC3_PROFILE_METRIC_COUNT; metric++) {
269	        struct lc3_profile_stats *stats;
270	        uint32_t value;
271	        int row;
272	
273	        if (!(profile->touched & (1u << metric)))
274	            continue;
275	
276	        stats = &profile->stats[metric];
277	        value = profile->current[metric];
278	
279	        if (!stats->count || value < stats->min)
280	            stats->min = value;
281	        if (!stats->count || value > stats->max)
282	            stats->max = value;
283	
284	        stats->total += value;
285	        stats->count++;
286	
287	        row = sample_row(metric);
288	        if (row >= 0 && stats->count <= LC3_PROFILE_WINDOW_FRAMES)
289	            profile->samples[row][stats->count - 1] = value;
290	    }
291	
292	    profile->frame_count++;
293	    profile->active = false;
294	
295	    if (profile->frame_count == LC3_PROFILE_WINDOW_FRAMES)
296	        profile->ready = true;
297	}
298	
299	void lc3_profile_report(struct lc3_profile *profile)
300	{
301	    if (!profile->frame_count)
302	        return;
303	
304	    report_window(profile);
305	    profile->sequence++;
306	    reset_window(profile);
307	}
