先回顾 neon_correlate 的完整实现（我已经读到了 ltpf_neon.h:220-280）：

```c
#ifndef correlate

LC3_HOT static void neon_correlate(
    const int16_t *a, const int16_t *b, int n, float *y, int nc)
{
    for ( ; nc >= 4; nc -= 4, b -= 4) {
        const int16_t *an = (const int16_t *)a;
        const int16_t *bn = (const int16_t *)b;

        int64x2_t v0 = vmovq_n_s64(0), v1 = v0, v2 = v0, v3 = v0;
        int16x4_t ax, b0, b1;

        b0 = vld1_s16(bn-4);

        for (int i=0; i < (n >> 4); i++ )
            for (int j = 0; j < 2; j++) {
                int32x4_t u0, u1, u2, u3;

                b1 = b0;
                b0 = vld1_s16(bn), bn += 4;
                ax = vld1_s16(an), an += 4;

                u0 = vmull_s16(ax, b0);
                u1 = vmull_s16(ax, vext_s16(b1, b0, 3));
                u2 = vmull_s16(ax, vext_s16(b1, b0, 2));
                u3 = vmull_s16(ax, vext_s16(b1, b0, 1));

                b1 = b0;
                b0 = vld1_s16(bn), bn += 4;
                ax = vld1_s16(an), an += 4;

                u0 = vmlal_s16(u0, ax, b0);
                u1 = vmlal_s16(u1, ax, vext_s16(b1, b0, 3));
                u2 = vmlal_s16(u2, ax, vext_s16(b1, b0, 2));
                u3 = vmlal_s16(u3, ax, vext_s16(b1, b0, 1));

                v0 = vpadalq_s32(v0, u0);
                v1 = vpadalq_s32(v1, u1);
                v2 = vpadalq_s32(v2, u2);
                v3 = vpadalq_s32(v3, u3);
            }

        *(y++) = (float)((int32_t)((vaddvq_s64(v0) + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((vaddvq_s64(v1) + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((vaddvq_s64(v2) + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((vaddvq_s64(v3) + (1 << 5)) >> 6));
    }

    for ( ; nc > 0; nc--)
        *(y++) = neon_dot(a, b--, n);
}
#endif /* correlate */

#ifndef TEST_NEON
#define correlate neon_correlate
#endif
```

让我理解 neon_correlate 的算法核心：

`correlate(a, b, n, y, nc)` 的语义：对 `nc` 个 lag，每个 lag l 计算 `dot(a, b - l, n)`，即 y[l] = sum_{i=0}^{n-1} a[i] * b[i-l]。

默认实现是逐个 lag 调 dot。

neon_correlate 的优化：一次处理 4 个连续的 lag（l, l+1, l+2, l+3）。关键技巧是 `vext_s16(b1, b0, k)` —— 把 b1 和 b0 拼接后取偏移 k 的 4 个元素，实现 b 的"滑窗"：对于相邻的 lag，b 的数据是错位 1 的，`vext_s16` 正好能从一个已经加载的 b 数据块里提取出错位版本，而 `a` 的数据 4 个 lag 共享（因为 a 不随 lag 变化）。

具体地：
- `ax = vld1_s16(an)` 加载 a 的 4 个元素，4 个 lag 共享。
- `b0` 是当前加载的 b 的 4 个元素（对应某个对齐位置）。
- `b1` 是前一个 b 块。
- `u0 = vmull(ax, b0)`：lag 0 对应 b0。
- `u1 = vmull(ax, vext(b1,b0,3))`：lag 1 对应 b 错位 1（用 vext 取 b1 的最后 1 个 + b0 的前 3 个）。
- `u2 = vmull(ax, vext(b1,b0,2))`：lag 2 错位 2。
- `u3 = vmull(ax, vext(b1,b0,1))`：lag 3 错位 3。

这样一次加载 a 和 b，就能同时推进 4 个 lag 的累加，比逐个调 dot 快 4 倍（减少了 a 的重复加载）。

这是标准的"correlation with sliding window / delay line"向量化技巧。

