`neon_correlate` 定义在 [src/ltpf_neon.h:224-279](third-party/liblc3-mve-pr/src/ltpf_neon.h#L224-L279)，完整是：

```c
#ifndef correlate

LC3_HOT static void neon_correlate(
    const int16_t *a, const int16_t *b, int n, float *y, int nc)
{
    for ( ; nc >= 4; nc -= 4, b -= 4) {
        const int16_t *an = (const int16_t *)a;
        const int16_t *bn = (const int16_t *)b;

        int64x2_t v0 = vmovq_n_s64(0), v1 = v0, v2 = v0, v3 = v0;
        int16x4_t ax, b0, b1;

        b0 = vld1_s16(bn-4);

        for (int i=0; i < (n >> 4); i++ )
            for (int j = 0; j < 2; j++) {
                int32x4_t u0, u1, u2, u3;

                b1 = b0;
                b0 = vld1_s16(bn), bn += 4;
                ax = vld1_s16(an), an += 4;

                u0 = vmull_s16(ax, b0);
                u1 = vmull_s16(ax, vext_s16(b1, b0, 3));
                u2 = vmull_s16(ax, vext_s16(b1, b0, 2));
                u3 = vmull_s16(ax, vext_s16(b1, b0, 1));

                b1 = b0;
                b0 = vld1_s16(bn), bn += 4;
                ax = vld1_s16(an), an += 4;

                u0 = vmlal_s16(u0, ax, b0);
                u1 = vmlal_s16(u1, ax, vext_s16(b1, b0, 3));
                u2 = vmlal_s16(u2, ax, vext_s16(b1, b0, 2));
                u3 = vmlal_s16(u3, ax, vext_s16(b1, b0, 1));

                v0 = vpadalq_s32(v0, u0);
                v1 = vpadalq_s32(v1, u1);
                v2 = vpadalq_s32(v2, u2);
                v3 = vpadalq_s32(v3, u3);
            }

        *(y++) = (float)((int32_t)((vaddvq_s64(v0) + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((vaddvq_s64(v1) + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((vaddvq_s64(v2) + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((vaddvq_s64(v3) + (1 << 5)) >> 6));
    }

    for ( ; nc > 0; nc--)
        *(y++) = neon_dot(a, b--, n);
}
#endif /* correlate */

#ifndef TEST_NEON
#define correlate neon_correlate
#endif
```

它的核心是**滑窗复用**：`correlate` 要对 `nc` 个连续 lag 各算一次 `dot`，相邻 lag 的 `b` 只错位 1 个元素。neon 用 `vext_s16(b1, b0, k)` 把上一轮已加载的 `b` 块错位 k 个元素，一次同时推进 4 个 lag、共享 `a` 的加载，把"逐 lag 调 dot"的重复加载省掉了。

MVE 版可以完全对齐这个思路，而且更简洁——`vmlaldavaq_s16` 一步就是 int16→int64 的 MAC，不像 neon 要 `vmull`→`vmlal`→`vpadal` 三阶段。MVE 向量是 8 元素，所以一次处理 8 个 lag：

```c
/**
 * Return vector of correlations
 */
#ifndef correlate

LC3_HOT static void mve_correlate(
    const int16_t *a, const int16_t *b, int n, float *y, int nc)
{
    for ( ; nc >= 8; nc -= 8, b -= 8) {
        const int16_t *an = a;
        const int16_t *bn = b;

        int64_t v0 = 0, v1 = 0, v2 = 0, v3 = 0,
                v4 = 0, v5 = 0, v6 = 0, v7 = 0;
        int16x8_t b0, b1;

        b0 = vldrhq_s16(bn - 8);

        for (int i = 0; i < (n >> 3); i++) {
            int16x8_t ax;

            b1 = b0;
            b0 = vldrhq_s16(bn), bn += 8;
            ax = vldrhq_s16(an), an += 8;

            v0 = vmlaldavaq_s16(v0, ax, b0);
            v1 = vmlaldavaq_s16(v1, ax, vextq_s16(b1, b0, 7));
            v2 = vmlaldavaq_s16(v2, ax, vextq_s16(b1, b0, 6));
            v3 = vmlaldavaq_s16(v3, ax, vextq_s16(b1, b0, 5));
            v4 = vmlaldavaq_s16(v4, ax, vextq_s16(b1, b0, 4));
            v5 = vmlaldavaq_s16(v5, ax, vextq_s16(b1, b0, 3));
            v6 = vmlaldavaq_s16(v6, ax, vextq_s16(b1, b0, 2));
            v7 = vmlaldavaq_s16(v7, ax, vextq_s16(b1, b0, 1));
        }

        *(y++) = (float)((int32_t)((v0 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v1 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v2 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v3 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v4 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v5 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v6 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v7 + (1 << 5)) >> 6));
    }

    for ( ; nc > 0; nc--)
        *(y++) = mve_dot(a, b--, n);
}
#endif /* correlate */

#ifndef TEST_MVE
#define correlate mve_correlate
#endif
```

滑窗偏移和 neon 完全对应：`vextq_s16(b1, b0, k)` 里 `b1` 是上一轮（更早的 8 个样本），`b0` 是当前轮，`k=7..1` 分别对应 lag 1..7 的 `b` 错位。

