#endif /* dot */

/**
 * Return vector of correlations
 */
#ifndef correlate

LC3_HOT static void mve_correlate(
    const int16_t *a, const int16_t *b, int n, float *y, int nc)
{
    for ( ; nc >= 8; nc -= 8, b -= 8) {
        const int16_t *an = a;
        const int16_t *bn = b;

        int64_t v0 = 0, v1 = 0, v2 = 0, v3 = 0,
                v4 = 0, v5 = 0, v6 = 0, v7 = 0;
        int16x8_t b0, b1;

        b0 = vldrhq_s16(bn - 8);

        for (int i = 0; i < (n >> 3); i++) {
            int16x8_t ax;

            b1 = b0;
            b0 = vldrhq_s16(bn); bn += 8;
            ax = vldrhq_s16(an); an += 8;

            v0 = vmlaldavaq_s16(v0, ax, b0);
            v1 = vmlaldavaq_s16(v1, ax, vextq_s16(b1, b0, 7));
            v2 = vmlaldavaq_s16(v2, ax, vextq_s16(b1, b0, 6));
            v3 = vmlaldavaq_s16(v3, ax, vextq_s16(b1, b0, 5));
            v4 = vmlaldavaq_s16(v4, ax, vextq_s16(b1, b0, 4));
            v5 = vmlaldavaq_s16(v5, ax, vextq_s16(b1, b0, 3));
            v6 = vmlaldavaq_s16(v6, ax, vextq_s16(b1, b0, 2));
            v7 = vmlaldavaq_s16(v7, ax, vextq_s16(b1, b0, 1));
        }

        *(y++) = (float)((int32_t)((v0 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v1 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v2 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v3 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v4 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v5 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v6 + (1 << 5)) >> 6));
        *(y++) = (float)((int32_t)((v7 + (1 << 5)) >> 6));
    }

    for ( ; nc > 0; nc--)
        *(y++) = mve_dot(a, b--, n);
}

#ifndef TEST_MVE
#define correlate mve_correlate
#endif

#endif /* correlate */

#endif /* __ARM_FEATURE_MVE & 1 */
