/**
 * Extract a vector from the concatenation of two vectors
 */

__attribute__((unused))
static int16x8_t vextq_s16(int16x8_t a, int16x8_t b, const int imm)
{
    int16x8_t r;

    for (int i = 0; i < 8; i++)
        r.e[i] = (i + imm < 8) ? a.e[i + imm] : b.e[i + imm - 8];

    return r;
}


#endif /* __ARM_FEATURE_MVE */
